import React, { useState } from 'react';
import InfoBox, { InfoBoxSection } from './components/InfoBox/InfoBox';
import Map from './components/Map/Map';
import './App.css';

const App: React.FC = () => {
  const [layersVisibility, setLayersVisibility] = useState<Record<string, boolean>>({
    'PresidenciasMunicipales': true,
    'PuntosWiFiCFE-4G': false,
    'PuntosWiFiCFE-FIBRA': false,
    'PuntosWiFiCFE-SATELITAL': false,
    'RegionesMesas': true
  });

  const handleToggle = (id: string) => {
    setLayersVisibility(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const sections: InfoBoxSection[] = [
    {
      title: '',
      items: [
        { id: 'PresidenciasMunicipales', label: 'Presidencias Municipales', color: '#000000', shape: 'circle', switch: true, checked: layersVisibility['PresidenciasMunicipales'] },
        { id: 'RegionesMesas', label: 'Regiones Mesas', color: '#999999', shape: 'square', switch: true, checked: layersVisibility['RegionesMesas'] }
      ]
    },
    {
      title: 'Puntos WiFi CFE',
      items: [
        { id: 'PuntosWiFiCFE-4G', label: '4G', color: '#9f2241', shape: 'circle', switch: true, checked: layersVisibility['PuntosWiFiCFE-4G'] },
        { id: 'PuntosWiFiCFE-FIBRA', label: 'Fibra oCobre', color: '#cda578', shape: 'circle', switch: true, checked: layersVisibility['PuntosWiFiCFE-FIBRA'] },
        { id: 'PuntosWiFiCFE-SATELITAL', label: 'Satelital', color: '#235b4e', shape: 'circle', switch: true, checked: layersVisibility['PuntosWiFiCFE-SATELITAL'] }
      ]
    }
  ];

  return (
    <div className="App">
      <div style={{ position: 'absolute', top: '10px', left: '10px', zIndex: 10 }}>
        <InfoBox title="Regiones Mesas de Paz" subtitle="Capas" sections={sections} onToggle={handleToggle} />
      </div>
      <Map layersVisibility={layersVisibility} />
    </div>
  );
};

export default App;

