import React, { useEffect, useRef } from 'react';
import maplibregl, { ExpressionSpecification } from 'maplibre-gl';
import { Protocol } from 'pmtiles';
import 'maplibre-gl/dist/maplibre-gl.css';

type MapProps = {
  layersVisibility: { [layerId: string]: boolean };
};

const Map: React.FC<MapProps> = ({ layersVisibility }) => {
  const mapContainerRef = useRef<HTMLDivElement | null>(null);
  const mapInstanceRef = useRef<maplibregl.Map | null>(null);
  const sourcesAddedRef = useRef(false);
  const popupRef = useRef<maplibregl.Popup | null>(null);

  const updateLayerVisibility = (map: maplibregl.Map) => {
    Object.entries(layersVisibility).forEach(([layerId, visible]) => {
      if (map.getLayer(layerId)) {
        map.setLayoutProperty(layerId, 'visibility', visible ? 'visible' : 'none');
      }
    });
  };

  useEffect(() => {
    if (!mapContainerRef.current) return;

    const protocol = new Protocol();
    maplibregl.addProtocol('pmtiles', protocol.tile);

    const map = new maplibregl.Map({
      container: mapContainerRef.current,
      style: 'https://api.maptiler.com/maps/01976666-b449-7252-86b5-3e7b3213a9e6/style.json?key=QAha5pFBxf4hGa8Jk5zv',
      center: [-101.98896, 23.07870],
      zoom: 4.47,
      attributionControl: false
    });

    map.on('load', () => {
      map.addControl(new maplibregl.AttributionControl({
        customAttribution: 'Secretaría de Gobernación',
        compact: true
      }), 'bottom-right');

      map.addSource('PresidenciasMunicipales', {
        type: 'vector',
        url: 'pmtiles://data/PresidenciasMunicipales.pmtiles'
      });
      map.addSource('PuntosWiFiCFE', {
        type: 'vector',
        url: 'pmtiles://data/PuntosWiFiCFE.pmtiles'
      });
      map.addSource('RegionesMesas', {
        type: 'vector',
        url: 'pmtiles://data/RegionesMesas.pmtiles'
      });

      // Colores Set2 de ColorBrewer
      const set2Colors = [
        '#66c2a5', '#fc8d62', '#8da0cb', '#e78ac3',
        '#a6d854', '#ffd92f', '#e5c494', '#b3b3b3'
      ];

      const matchValues: (string | number)[] = [];
      for (let i = 1; i <= 266; i++) {
        const color = set2Colors[i % set2Colors.length];
        matchValues.push(i, color);
      }

      const matchExpression = [
  'match',
  ['get', '_REGION'],
  ...matchValues,
  '#cccccc'
] as unknown as ExpressionSpecification;


      map.addLayer({
        id: 'RegionesMesas',
        type: 'fill',
        source: 'RegionesMesas',
        'source-layer': 'RegionesMesas_tile',
        paint: {
          'fill-color': matchExpression,
          'fill-opacity': 0.4,
          'fill-outline-color': '#555555'
        }
      });

      map.addLayer({
        id: 'PresidenciasMunicipales',
        type: 'circle',
        source: 'PresidenciasMunicipales',
        'source-layer': 'PresidenciasMunicipales_tile',
        paint: {
          'circle-radius': 1.5,
          'circle-color': '#000000'
        }
      });

      const wifiTypes = [
        { id: 'PuntosWiFiCFE-4G', tipo: '4G', color: '#9f2241' },
        { id: 'PuntosWiFiCFE-FIBRA', tipo: 'FIBRA O COBRE', color: '#cda578' },
        { id: 'PuntosWiFiCFE-SATELITAL', tipo: 'SATELITAL', color: '#235b4e' }
      ];

      wifiTypes.forEach(({ id, tipo, color }) => {
        map.addLayer({
          id,
          type: 'circle',
          source: 'PuntosWiFiCFE',
          'source-layer': 'PuntosWiFiCFE_tile',
          filter: ['==', ['get', 'TECNOLOGIA'], tipo],
          paint: {
            'circle-radius': 1.2,
            'circle-color': color,
            'circle-stroke-color': '#ffffff',
            'circle-stroke-width': 0
          }
        });
      });

      // POPUPS
      map.on('mouseenter', 'PresidenciasMunicipales', (e) => {
        map.getCanvas().style.cursor = 'pointer';
        popupRef.current?.remove();
        const props = e.features?.[0]?.properties;
        if (props) {
          popupRef.current = new maplibregl.Popup({ closeButton: false, closeOnClick: false })
            .setLngLat(e.lngLat)
            .setHTML(`<strong>Entidad:</strong> ${props['entidad']}<br/><strong>Municipio:</strong> ${props['municipio']}<br/><strong>Dirección:</strong> ${props['direccion']}`)
            .addTo(map);
        }
      });

      const handleWiFiPopup = (e: any) => {
        map.getCanvas().style.cursor = 'pointer';
        popupRef.current?.remove();
        const props = e.features?.[0]?.properties;
        if (props) {
          popupRef.current = new maplibregl.Popup({ closeButton: false, closeOnClick: false })
            .setLngLat(e.lngLat)
            .setHTML(`<strong>Nombre:</strong> ${props['INMUEBLE NOMBRE']}<br/><strong>Tipo inmueble:</strong> ${props['TIPO INMUEBLE']}<br/><strong>AP:</strong> ${props['NOMBRE AP']}<br/><strong>Tecnología:</strong> ${props['TECNOLOGIA']}`)
            .addTo(map);
        }
      };

      wifiTypes.forEach(({ id }) => {
        map.on('mouseenter', id, handleWiFiPopup);
      });

      map.on('mouseenter', 'RegionesMesas', (e) => {
        map.getCanvas().style.cursor = 'pointer';
        popupRef.current?.remove();
        const props = e.features?.[0]?.properties;
        if (props) {
          popupRef.current = new maplibregl.Popup({ closeButton: false, closeOnClick: false })
            .setLngLat(e.lngLat)
            .setHTML(`
              <strong>Entidad:</strong> ${props['NOMGEO']}<br/>
              <strong>Región:</strong> ${props['_REGION']}<br/>
              <strong>Nombre de la Región:</strong> ${props['_NOM_REGION']}
            `)
            .addTo(map);
        }
      });

      map.on('mouseleave', 'RegionesMesas', () => {
        map.getCanvas().style.cursor = '';
        popupRef.current?.remove();
      });

      map.on('mouseleave', () => {
        map.getCanvas().style.cursor = '';
        popupRef.current?.remove();
      });

      sourcesAddedRef.current = true;
      mapInstanceRef.current = map;
      updateLayerVisibility(map);
    });

    return () => {
      map.remove();
      sourcesAddedRef.current = false;
      maplibregl.removeProtocol('pmtiles');
    };
  }, []);

  useEffect(() => {
    if (mapInstanceRef.current && sourcesAddedRef.current) {
      updateLayerVisibility(mapInstanceRef.current);
    }
  }, [layersVisibility]);

  return <div ref={mapContainerRef} style={{ width: '100%', height: '100vh' }} />;
};

export default Map;


